import type { Json } from '@zeespare/shared/database.types'
import type { NextRequest } from 'next/server'
import {
  IMPORTS_BUCKET,
  badRequest,
  guardMutation,
  isRecord,
  jsonResponse,
  parseUuid,
  rpcErrorResponse,
  unexpectedErrorResponse,
} from '@/lib/imports/route'
import { requireSessionRoute, type ServerClient } from '@/lib/imports/route-auth'

const ROUTE = 'POST /api/imports'

/**
 * Creates an import: `{batch_id, organization_id, files}` goes to import_create_batch unchanged
 * (the batch id is generated by the client, so a retry returns the same batch). Each returned
 * file then gets a signed upload URL for its original, signed with the user's own client (the
 * Storage insert policy is checked at signing) and `upsert: false`. A file whose URL cannot be
 * signed gets `upload_url: null` and `upload_error` (`exists` when the original is already
 * stored, e.g. on a retry); originals are an audit copy, so the import goes on without it.
 */
export async function POST(request: NextRequest) {
  const guard = await guardMutation(request)
  if (!guard.ok) return guard.response
  const batchId = parseUuid(guard.body.batch_id)
  if (!batchId) return badRequest('batch_id')
  const organizationId = parseUuid(guard.body.organization_id)
  if (!organizationId) return badRequest('organization_id')
  if (!Array.isArray(guard.body.files)) return badRequest('files')

  const session = await requireSessionRoute()
  if (!session.ok) return session.response
  try {
    const { data, error } = await session.supabase.rpc('import_create_batch', {
      p_batch_id: batchId,
      p_organization_id: organizationId,
      p_files: guard.body.files as Json,
    })
    if (error) return rpcErrorResponse(error, ROUTE)
    return jsonResponse(await withUploadUrls(session.supabase, data))
  } catch (error) {
    return unexpectedErrorResponse(error, ROUTE)
  }
}

async function withUploadUrls(supabase: ServerClient, result: Json): Promise<Json> {
  if (!isRecord(result) || !Array.isArray(result.files)) return result
  const files = await Promise.all(
    result.files.map(async (file) => {
      if (!isRecord(file) || typeof file.storage_path !== 'string') return file
      const signed = await signUpload(supabase, file.storage_path, file.file_no)
      return { ...file, ...signed }
    }),
  )
  return { ...result, files } as Json
}

type SignedUpload =
  | { upload_url: string; upload_token: string }
  | { upload_url: null; upload_token: null; upload_error: 'exists' | 'failed' }

async function signUpload(
  supabase: ServerClient,
  path: string,
  fileNo: unknown,
): Promise<SignedUpload> {
  try {
    const { data, error } = await supabase.storage
      .from(IMPORTS_BUCKET)
      .createSignedUploadUrl(path, { upsert: false })
    if (data && !error) return { upload_url: data.signedUrl, upload_token: data.token }
    const status = error && 'status' in error ? error.status : undefined
    const exists = status === 409 || /already exists/i.test(error?.message ?? '')
    if (!exists) {
      console.warn('imports: upload URL not signed', {
        file_no: fileNo,
        status: status ?? null,
        message: error?.message ?? null,
      })
    }
    return { upload_url: null, upload_token: null, upload_error: exists ? 'exists' : 'failed' }
  } catch (error) {
    console.warn('imports: upload URL not signed', {
      file_no: fileNo,
      message: error instanceof Error ? error.message : String(error),
    })
    return { upload_url: null, upload_token: null, upload_error: 'failed' }
  }
}
